function deepFreeze(value) {
  if (value && typeof value === 'object' && !Object.isFrozen(value)) {
    for (const child of Object.values(value)) deepFreeze(child);
    Object.freeze(value);
  }
  return value;
}

export const DB = deepFreeze(raw);
const rarityCode = Object.freeze({ 'Thường': 'common', 'Ít gặp': 'uncommon', 'Hiếm': 'rare', 'Sử thi': 'epic', 'Huyền thoại': 'legendary' });
const displayEntry = (entry) => Object.freeze({
  ...entry,
  rarity: rarityCode[entry.rarity] ?? entry.rarity,
  rarityLabel: entry.rarity,
});
export const CROP = Object.freeze(Object.fromEntries(DB.crops.map((entry) => [entry.id, displayEntry(entry)])));
export const CREATURE = Object.freeze(Object.fromEntries(DB.animals.map((entry) => [entry.id, displayEntry(entry)])));
export const RECIPE = Object.freeze(Object.fromEntries(DB.recipes.map((entry) => [entry.id, entry])));
export const EXPANSION = Object.freeze(Object.fromEntries(DB.expansions.map((entry) => [entry.id, entry])));
export const REWARDS = Object.freeze(Object.fromEntries(DB.levels.map((entry) => [entry.level, entry])));
// Level-500 roadmap §12: levels above TAN_SUC_LEVEL (bậc Tận Sức) stay hidden until a garden reaches it.
export const MAX_LEVEL = DB.levels.length;
export const TAN_SUC_LEVEL = 100;
